        // Consolidated helper for updating the Turbo button
        private void UpdateTurboButton(bool turboOn)
        {
            // How long the current setting lasts: a change made "only while SMD Win is open" is restored on close.
            bool temporary = SMDWin.Services.TurboRestore.HasPendingFor(SMDWin.Services.TurboRestore.Part.Turbo);
            string stateText = temporary ? LanguageService.S("Stress", "TurboStateTemporary")
                             : !turboOn ? LanguageService.S("Stress", "TurboStatePermanent")
                             : "";
            if (TxtBtnTurbo != null)
            {
                string label = turboOn ? LanguageService.S("Stress", "TurboOn") : LanguageService.S("Stress", "TurboOff");
                TxtBtnTurbo.Text = temporary ? label + " · " + LanguageService.S("Stress", "TurboTagTemporary") : label;
                TxtBtnTurbo.Foreground = (System.Windows.Media.Brush)TryFindResource("TextPrimaryBrush");
            }
            if (FindName("BtnTurbo") is FrameworkElement turboBtn)
                turboBtn.ToolTip = stateText.Length > 0 ? stateText : null;
            if (FindName("TurboStateBadge") is Border badge && FindName("TxtTurboStateBadge") is TextBlock badgeText)
            {
                badge.Visibility = stateText.Length > 0 ? Visibility.Visible : Visibility.Collapsed;
                badgeText.Text = temporary ? LanguageService.S("Stress", "TurboTagTemporary") : LanguageService.S("Stress", "TurboTagPermanent");
                badge.ToolTip = stateText;
                badgeText.SetResourceReference(TextBlock.ForegroundProperty, temporary ? "StatusCheckBrush" : "TextSecondaryBrush");
            }
            if (FindName("IconTurbo") is System.Windows.Shapes.Path iconTurbo)
            {
                // ON:  ⚡ green; OFF: ⚡ crossed out, red
                iconTurbo.Data = SMDWin.Services.FluentIcons.Get(turboOn ? "flash" : "flash_off");
                iconTurbo.Stroke = null;
                iconTurbo.Fill = turboOn
                    ? new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(34, 197, 94))   // green
                    : new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(239, 68, 68));  // red
            }
        }

        private static IEnumerable<T> FindVisualChildren<T>(DependencyObject obj) where T : DependencyObject
        {
            for (int i = 0; i < System.Windows.Media.VisualTreeHelper.GetChildrenCount(obj); i++)
            {
                var child = System.Windows.Media.VisualTreeHelper.GetChild(obj, i);
                if (child is T t) yield return t;
                foreach (var childOfChild in FindVisualChildren<T>(child))
                    yield return childOfChild;
            }
        }

        /// <summary>The rule for the start / stop button of a test or a scan: while it runs, the button is a red "Stop";
        /// at the end it returns to its usual look (<paramref name="idle"/>).</summary>
        internal static void SetStopLook(System.Windows.Controls.Button? b, bool running,
            Wpf.Ui.Controls.ControlAppearance idle = Wpf.Ui.Controls.ControlAppearance.Primary)
        {
            if (b is Wpf.Ui.Controls.Button ui)
            {
                ui.Appearance = running ? Wpf.Ui.Controls.ControlAppearance.Danger : idle;
                // the red "Stop" button always has white text and icon (in both themes, also when not hovered);
                // when it returns, the text takes the usual colour of the idle look
                bool whiteIdle = idle == Wpf.Ui.Controls.ControlAppearance.Primary;
                ApplyStopForeground(ui, running || whiteIdle);
                ui.Dispatcher.BeginInvoke(new Action(() => ApplyStopForeground(ui, running || whiteIdle)),
                    System.Windows.Threading.DispatcherPriority.Loaded);
            }
        }

        private static void ApplyStopForeground(System.Windows.Controls.Button b, bool white)
        {
            try
            {
                if (white) b.Foreground = System.Windows.Media.Brushes.White;
                else b.SetResourceReference(System.Windows.Controls.Control.ForegroundProperty, "TextPrimaryBrush");
                foreach (var label in FindVisualChildren<System.Windows.Controls.TextBlock>(b))
                {
                    if (white) label.Foreground = System.Windows.Media.Brushes.White;
                    else label.SetResourceReference(System.Windows.Controls.TextBlock.ForegroundProperty, "TextPrimaryBrush");
                }
                foreach (var icon in FindVisualChildren<System.Windows.Shapes.Path>(b))
                {
                    if (icon.Stroke != null)
                    {
                        if (white) icon.Stroke = System.Windows.Media.Brushes.White;
                        else if (ReferenceEquals(icon.Stroke, System.Windows.Media.Brushes.White)) icon.SetResourceReference(System.Windows.Shapes.Shape.StrokeProperty, "StatusOkBrush");
                    }
                    if (icon.Fill != null && icon.Fill != System.Windows.Media.Brushes.Transparent)
                    {
                        if (white) icon.Fill = System.Windows.Media.Brushes.White;
                        else if (ReferenceEquals(icon.Fill, System.Windows.Media.Brushes.White)) icon.SetResourceReference(System.Windows.Shapes.Shape.FillProperty, "TextPrimaryBrush");
                    }
                }
            }
            catch (Exception ex) { AppLogger.Debug($"ApplyStopForeground: {ex.Message}"); }
        }

        /// <summary>
        /// The tab / filter chosen in a row of WPF-UI buttons. The chosen one is a lighter, raised pill (SelBtn*, variant B);
        /// the others stay neutral buttons. Blue (Primary) is no longer used here: it is only for the main action.
        /// </summary>
        /// <summary>The button sits on a tab track (a close parent with Tag = "SegTrack").</summary>
        internal static bool IsOnSegmentTrack(FrameworkElement b)
        {
            DependencyObject? p = b;
            for (int i = 0; i < 4 && p != null; i++)
            {
                p = (p as FrameworkElement)?.Parent ?? System.Windows.Media.VisualTreeHelper.GetParent(p);
                if (p is FrameworkElement fe && fe.Tag is string t && t == "SegTrack") return true;
            }
            return false;
        }

        private static readonly HashSet<string> _offTrackLogged = new();

        internal static void SetTabButtonActive(Wpf.Ui.Controls.Button? b, bool active)
        {
            if (b == null) return;
            b.Appearance = Wpf.Ui.Controls.ControlAppearance.Secondary;
            b.BorderThickness = new Thickness(1);
            bool onTrack = IsOnSegmentTrack(b);
            b.MouseOverBorderBrush = System.Windows.Media.Brushes.Transparent;
            b.PressedBorderBrush = System.Windows.Media.Brushes.Transparent;
            if (active && onTrack)
            {
                // on the grey band: a raised white pill
                b.SetResourceReference(System.Windows.Controls.Control.BackgroundProperty, "SelBtnBg");
                b.SetResourceReference(System.Windows.Controls.Control.BorderBrushProperty, "SelBtnBorderBrush");
                b.ClearValue(UIElement.EffectProperty);   // no shadow on a button with text: it blurs the text
                b.FontWeight = FontWeights.SemiBold;
            }
            else if (active)
            {
                // choice groups sit on the grey track (Tag="SegTrack"); for one outside it the chosen button only gets the track's
                // grey background — discreet — and it is logged once, so it can be moved onto a track
                b.SetResourceReference(System.Windows.Controls.Control.BackgroundProperty, "SegTrackBrush");
                b.BorderBrush = System.Windows.Media.Brushes.Transparent;
                b.ClearValue(UIElement.EffectProperty);
                b.FontWeight = FontWeights.SemiBold;
                string who = string.IsNullOrEmpty(b.Name) ? (b.Content?.ToString() ?? "?") : b.Name;
                if (_offTrackLogged.Add(who))
                    AppLogger.Debug($"SetTabButtonActive: '{who}' is not on a segment track (Tag=\"SegTrack\") — shown with the track background");
            }
            else
            {
                // on the grey track the other tabs are text only; elsewhere they stay white buttons with a fine outline
                if (onTrack)
                {
                    b.Background = System.Windows.Media.Brushes.Transparent;
                    b.BorderBrush = System.Windows.Media.Brushes.Transparent;
                }
                else
                {
                    b.ClearValue(System.Windows.Controls.Control.BackgroundProperty);
                    b.SetResourceReference(System.Windows.Controls.Control.BorderBrushProperty, "BtnNeutralBorderBrush");
                    b.SetResourceReference(Wpf.Ui.Controls.Button.MouseOverBorderBrushProperty, "BtnNeutralBorderBrush");
                    b.SetResourceReference(Wpf.Ui.Controls.Button.PressedBorderBrushProperty, "BtnNeutralBorderBrush");
                }
                b.ClearValue(UIElement.EffectProperty);
                b.ClearValue(System.Windows.Controls.Control.FontWeightProperty);
            }
            b.ClearValue(System.Windows.Controls.Control.ForegroundProperty);
            string fg = !active ? "TextPrimaryBrush" : onTrack ? "SelBtnFg" : "TextPrimaryBrush";

            foreach (var icon in FindVisualChildren<System.Windows.Shapes.Path>(b))
            {
                if (icon.Stroke != null)
                    icon.SetResourceReference(System.Windows.Shapes.Shape.StrokeProperty, fg);
                if (icon.Fill != null && icon.Fill != System.Windows.Media.Brushes.Transparent)
                    icon.SetResourceReference(System.Windows.Shapes.Shape.FillProperty, fg);
            }

            foreach (var label in FindVisualChildren<System.Windows.Controls.TextBlock>(b))
                label.SetResourceReference(System.Windows.Controls.TextBlock.ForegroundProperty, fg);
            if (active) b.SetResourceReference(System.Windows.Controls.Control.ForegroundProperty, fg);
        }

        private void SetStressButtonIconState(Button? btn, bool isRunning)
        {
            if (btn == null) return;
            try
            {
                var path = FindVisualChildren<System.Windows.Shapes.Path>(btn).FirstOrDefault();
                if (path != null)
                {
                    if (isRunning) { path.Stroke = System.Windows.Media.Brushes.White; return; }   // on the red button: a white icon
                    path.Stroke = (Brush)(TryFindResource(isRunning ? "StatusCritBrush" : "StatusOkBrush")
                        ?? new SolidColorBrush(isRunning ? WpfColor.FromRgb(239, 68, 68) : WpfColor.FromRgb(34, 197, 94)));
                }
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }
        }

