        private static string FormatKBps(float kbps)
        {
            if (kbps >= 1024 * 1024) return $"{kbps / 1024 / 1024:F1} GB/s";
            if (kbps >= 1024)        return $"{kbps / 1024:F1} MB/s";
            if (kbps >= 1)           return $"{kbps:F0} KB/s";
            return "0 KB/s";
        }

        /// <summary>Compact disk R/W: "R 11 · W 2 KB/s" — single shared unit, fits at FontSize 20.</summary>
        private static string FormatDiskRW(float readKBps, float writeKBps)
        {
            // Use the larger value to pick the shared unit
            float maxV = Math.Max(readKBps, writeKBps);
            if (maxV >= 1024 * 1024) return $"R {readKBps/1024/1024:F1} · W {writeKBps/1024/1024:F1} GB/s";
            if (maxV >= 1024)        return $"R {readKBps/1024:F1} · W {writeKBps/1024:F1} MB/s";
            return $"R {readKBps:F0} · W {writeKBps:F0} KB/s";
        }


        private static (string r, string w) FormatDiskRWParts(float readKBps, float writeKBps)
        {
            float maxV = Math.Max(readKBps, writeKBps);
            if (maxV >= 1024 * 1024) return ($"R {readKBps/1024/1024:F1}", $"W {writeKBps/1024/1024:F1} GB/s");
            if (maxV >= 1024)        return ($"R {readKBps/1024:F1}",      $"W {writeKBps/1024:F1} MB/s");
            return ($"R {readKBps:F0}", $"W {writeKBps:F0} KB/s");
        }

        // Disk I/O via PerformanceCounter (system-wide, KB/s + Active Time %)
        private System.Diagnostics.PerformanceCounter? _pcDiskRead;
        private System.Diagnostics.PerformanceCounter? _pcDiskWrite;
        private System.Diagnostics.PerformanceCounter? _pcDiskActive;
        private System.Diagnostics.PerformanceCounter? _pcDiskAvgMs;
        private float _lastDiskActivePct = 0f;
        private System.Windows.Controls.TextBlock? _diskTooltipTb;
        private float _lastDiskAvgMs     = 0f;
        private int   _diskCounterFreezeCount = 0;
        private float _diskLastReadKBs   = -1f;     // for freeze detection
        private float _diskLastWriteKBs  = -1f;
        private int  _diskCounterFailCount    = 0;
        private bool _diskCounterUnavailable  = false;

        private void GetSystemDiskIO(out float readKBs, out float writeKBs)
        {
            readKBs = 0; writeKBs = 0;
            if (_diskCounterUnavailable) return;
            try
            {
                if (_pcDiskRead == null || _pcDiskWrite == null)
                {
                    _pcDiskRead  ??= new System.Diagnostics.PerformanceCounter(
                        "PhysicalDisk", "Disk Read Bytes/sec",    "_Total", true);
                    _pcDiskWrite ??= new System.Diagnostics.PerformanceCounter(
                        "PhysicalDisk", "Disk Write Bytes/sec",   "_Total", true);
                    _pcDiskActive ??= new System.Diagnostics.PerformanceCounter(
                        "PhysicalDisk", "% Idle Time",            "_Total", true);
                    _pcDiskAvgMs  ??= new System.Diagnostics.PerformanceCounter(
                        "PhysicalDisk", "Avg. Disk sec/Transfer", "_Total", true);
                    _pcDiskRead.NextValue(); _pcDiskWrite.NextValue();
                    _pcDiskActive.NextValue(); _pcDiskAvgMs.NextValue();
                    return;
                }

                float r  = _pcDiskRead.NextValue();
                float w2 = _pcDiskWrite.NextValue();
                readKBs  = r  / 1024f;
                writeKBs = w2 / 1024f;
                if (readKBs  > 10_000_000f) readKBs  = 0f;
                if (writeKBs > 10_000_000f) writeKBs = 0f;

                bool readChanged  = Math.Abs(readKBs  - _diskLastReadKBs)  > 2f;
                bool writeChanged = Math.Abs(writeKBs - _diskLastWriteKBs) > 2f;
                if (!readChanged && !writeChanged)
                    _diskCounterFreezeCount++;
                else
                    _diskCounterFreezeCount = 0;
                _diskLastReadKBs  = readKBs;
                _diskLastWriteKBs = writeKBs;

                if (_diskCounterFreezeCount > 30) // not 10 — too aggressive on Boot Camp
                {
                    AppLogger.Debug("DiskIO counters frozen — resetting");
                    try { _pcDiskRead?.Dispose();  } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                    try { _pcDiskWrite?.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                    try { _pcDiskActive?.Dispose();} catch (Exception ex) { AppLogger.Debug(ex.Message); }
                    try { _pcDiskAvgMs?.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                    _pcDiskRead = _pcDiskWrite = _pcDiskActive = _pcDiskAvgMs = null;
                    _diskCounterFreezeCount = 0;
                    return;
                }

                float idlePct = _pcDiskActive?.NextValue() ?? 100f;
                float activeFromIdle = Math.Clamp(100f - idlePct, 0f, 100f);
                float tput = readKBs + writeKBs;
                if (activeFromIdle < 1f && tput > 64f)
                    activeFromIdle = Math.Clamp(tput / 51200f * 100f, 1f, 100f);
                _lastDiskActivePct = activeFromIdle;

                float avgSec = _pcDiskAvgMs?.NextValue() ?? 0f;
                _lastDiskAvgMs = avgSec * 1000f;

                // A successful read — an occasional (rare, transient) failure no longer counts towards the give-up threshold below.
                _diskCounterFailCount = 0;
            }
            catch (Exception ex)
            {
                AppLogger.Warning(ex, "MainWindow.GetSystemDiskIO");
                // Reset la exceptie — contoarele pot fi in stare invalida
                try { _pcDiskRead?.Dispose();  } catch (Exception ex2) { AppLogger.Debug(ex2.Message); }
                try { _pcDiskWrite?.Dispose(); } catch (Exception ex2) { AppLogger.Debug(ex2.Message); }
                try { _pcDiskActive?.Dispose();} catch (Exception ex2) { AppLogger.Debug(ex2.Message); }
                try { _pcDiskAvgMs?.Dispose(); } catch (Exception ex2) { AppLogger.Debug(ex2.Message); }
                _pcDiskRead = _pcDiskWrite = _pcDiskActive = _pcDiskAvgMs = null;

                _diskCounterFailCount++;
                if (_diskCounterFailCount >= 3)
                {
                    _diskCounterUnavailable = true;
                    AppLogger.Warning($"GetSystemDiskIO: {_diskCounterFailCount} consecutive failures —" +
                        "PerformanceCounter 'PhysicalDisk' seems unavailable on this system." +
                        "Giving up for the rest of the session (Disk I/O on the Dashboard will not update).");
                }
            }
        }
